head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.contnId;
scwin.fileRowcount;
scwin.vScrenID = "ULDSTF07245.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_single_read = function() {
    //기업분석보고서/신규상장기업분석보고서 개별조회
    trs_Read.Action = "/IRMgt.do?method=readAnalysisReport&contnId=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyName = "toinb_dataid4";
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_irCeoRoomSingle,O:pOutput2=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_update = function() {
    //기업분석보고서/신규상장기업분석보고서 수정
    var pageGbn = $c.stf.getObjectValue(txb_page_gbn);
    var kosdaqBbsTpCd = $c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd);
    //alert(kosdaqBbsTpCd);

    if (txb_isur_cd.getValue() == "" || txb_isur_cd.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (!scwin.checkMaxLength1(txb_wrt_inst_nm, 80, "작성기관")) {
        txb_wrt_inst_nm.setValue("");
        txb_wrt_inst_nm.focus();
        return false;
    }
    if (txb_title.getValue() == "" || txb_title.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        txb_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(txb_title, 200, "제목")) {
        txb_title.setValue("");
        txb_title.focus();
        return false;
    }
    if (!scwin.checkMaxLength2(maindoc_contn, 2000, "내용")) {
        maindoc_contn.text = "";
        maindoc_contn.focus();
        return false;
    }
    if (!$c.ut.isDate(txb_noti_dd.getValue())) {
        $c.win.alert("[게시일자]를 확인하세요.");
        txb_noti_dd.focus();
        return false;
    }
    var rtn = confirm('내용을 수정 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_Update.Action = "/IRMgt.do?method=modifyAnalysisReport&contn_id=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&page_gbn=" + pageGbn + "&kosdaq_bbs_tp_cd=" + kosdaqBbsTpCd;
        trs_Update.KeyName = "toinb_dataid4";
        trs_Update.KeyValue = "JSP(I:pInput1=dts_irCeoRoomSingle,I:pInput2=dts_fileList)";
        trs_Update.Post();
    }
};
scwin.fn_save = function() {
    //기업분석보고서/신규상장기업분석보고서 등록
    /* 파일업로드 */
    if (txb_isur_cd.getValue() == "" || txb_isur_cd.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사(명)"));
        txb_isur_cd.focus();
        return;
    }
    if (!scwin.checkMaxLength1(txb_wrt_inst_nm, 80, "작성기관")) {
        txb_wrt_inst_nm.setValue("");
        txb_wrt_inst_nm.focus();
        return false;
    }
    if (txb_title.getValue() == "" || txb_title.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        txb_title.focus();
        return;
    }
    if (!scwin.checkMaxLength1(txb_title, 200, "제목")) {
        txb_title.setValue("");
        txb_title.focus();
        return false;
    }
    if (!scwin.checkMaxLength2(maindoc_contn, 2000, "내용")) {
        maindoc_contn.text = "";
        maindoc_contn.focus();
        return false;
    }
    if (!$c.ut.isDate(txb_noti_dd.getValue())) {
        $c.win.alert("[게시일자]를 확인하세요.");
        txb_noti_dd.focus();
        return false;
    }
    var rtn = confirm('위사항을 입력 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        trs_Save.Action = "/IRMgt.do?method=registerAnalysisReport" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_irCeoSaveInfo,I:pFile1=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_delete = function() {
    //기업분석보고서/신규상장기업분석보고서 삭제

    //var pageGbn = "report2";
    var pageGbn = $c.stf.getObjectValue(txb_page_gbn);
    var rtn = confirm('내용을 삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_irCeoRoomSingle.insertRow();
        dts_irCeoRoomSingle.setCellData(2, "CONTN_ID", dts_irCeoRoomSingle.getCellData(1, "CONTN_ID"));
        dts_irCeoRoomSingle.setCellData(2, "KOSDAQ_BBS_TP_CD", dts_irCeoRoomSingle.getCellData(1, "KOSDAQ_BBS_TP_CD"));
        trs_Delete.Action = "/IRMgt.do?method=removeAnalysisReport" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&page_gbn=" + pageGbn;
        trs_Delete.KeyName = "toinb_dataid4";
        trs_Delete.KeyValue = "JSP(I:pInput=dts_irCeoRoomSingle)";
        trs_Delete.Post();
    }
};



// CUD용 Header
scwin.fn_SetIrInfoHeader = function() {
    dts_irCeoSaveInfo.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_ANALYSIS_REPORT_INOUT";
    dts_irCeoSaveInfo.Reset();
    dts_irCeoSaveInfo.insertRow();
};


// CUD용 Header
scwin.fn_SetIrDataHeader = function() {
    dts_irCeoSaveData.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BIZSPT_ANALYSIS_REPORT_INOUT";
    dts_irCeoSaveData.Reset();
    dts_irCeoSaveData.AddRow();
};


//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/IRMgt.do?method=downAnalysisReport" + "&file_id=" + scwin.contnId + "&attach_seq=" + attach_seq;
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};


// 시장구분 라디오버튼
scwin.fn_Init = function() {
    $c.stf.setObjectValue(rdo_mkt_tp_cd, js_market);
    if (js_market == "1" || js_market == "2" || js_market == "6") {
        rdo_mkt_tp_cd.setDisabled(true);
    } else {
        // 콘트롤 잠그기
        rdo_mkt_tp_cd.setDisabled(false);
        rdo_mkt_tp_cd.addClass("TopCondition_Blue");
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
    if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "13") {
        if (scwin.contnId == 'input') {
            $c.stf.setObjectValue(txb_title, $c.stf.getObjectValue(txb_com_abbrv) + " 기업의 사업모델 평가보고서 및 기업 계속성 보고서");
        }
    }
};
scwin.trs_Read_OnSuccess = function() {

};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Update_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "등록"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.save_onclick = function() {
    if (scwin.contnId != "input") {
        scwin.fn_update();
    } else {
        scwin.fn_save();
    }
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_lineadd_onclick = function() {
    if (scwin.contnId != "input") {
        scwin.fileRowcount = dts_fileList.getTotalRow();
    }
    scwin.fileRowcount++;
    if (scwin.fileRowcount >= 4) {
        $c.win.alert("더이상 추가하실수 없습니다.");
        scwin.fileRowcount = 4;
    } else {
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() != "") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
            file_name.setValue(inf_find.getValue());
        } else {
            $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
        }
    }
};
scwin.btn_linedelete_onclick = function() {
    if (scwin.fileRowcount > 0) scwin.fileRowcount--;
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.grd_userlist_OnClick = function(row, colid) {
    if (row == 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
    if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "13") {
        if (scwin.contnId == 'input') {
            $c.stf.setObjectValue(txb_title, $c.stf.getObjectValue(txb_com_abbrv) + " 기업의 사업모델 평가보고서 및 기업 계속성 보고서");
        }
    }
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(txb_noti_dd);
};
scwin.rdo_kosdaq_bbs_tp_cd_onclick = function() {
    if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "12" || $c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "13") {
        // 신규상장기업분석보고서,성장성보고서
        $c.stf.showObj(label_3, true);
        $c.stf.showObj(rdo_approv_yn, true);
        $c.stf.setObjectValue(txb_page_gbn, "report5");
        if (scwin.contnId == 'input') {
            if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "13") {
                $c.stf.setObjectValue(txb_title, $c.stf.getObjectValue(txb_com_abbrv) + " 기업의 사업모델 평가보고서 및 기업 계속성 보고서");
            }
        }
    } else {
        $c.stf.showObj(label_3, false);
        $c.stf.showObj(rdo_approv_yn, false);
        $c.stf.setObjectValue(rdo_approv_yn, "");
        $c.stf.setObjectValue(txb_page_gbn, "report2");
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    reId = $c.frame.path("../").fn_getId;
    scwin.contnId = reId();
    $c.stf.showObj(wrtr_id, false);
    $c.stf.showObj(txb_page_gbn, false);
    $c.stf.showObj(txb_wrt_dd, true);
    $c.stf.showObj(file_name, false);
    $c.stf.showObj(inf_find, false);
    scwin.fn_Init(); //시장구분

    //수정화면 onload
    if (scwin.contnId != "input") {
        scwin.fn_single_read();
        if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "10") {
            // 기업분석보고서
            $c.stf.setObjectValue(txb_page_gbn, "report2");
        } else if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "12") {
            // 신규상장기업분석보고서
            $c.stf.setObjectValue(txb_page_gbn, "report5");
        } else if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "23") {
            //기업분석보고서(영문)
            $c.stf.setObjectValue(txb_page_gbn, "report2");
        } else if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "13") {
            // 성장성보고서
            $c.stf.setObjectValue(txb_page_gbn, "report5");
        } else {
            $c.stf.setObjectValue(txb_page_gbn, "report2");
        }
        if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "10" || $c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "23") {
            // 기업분석보고서, 기업분석보고서(영문), 성장성보고서
            $c.stf.showObj(label_3, false);
            $c.stf.showObj(rdo_approv_yn, false);
        } else {
            $c.stf.showObj(label_3, true);
            $c.stf.showObj(rdo_approv_yn, true);
        }
    } else {
        $c.stf.showObj(btn_delete, false);
        $c.stf.showObj(label_3, false);
        $c.stf.showObj(rdo_approv_yn, false);

        //등록화면 onload
        scwin.fn_SetIrInfoHeader();
        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        scwin.fileRowcount = 0;
        wrtr_id.setValue(js_id);
        txb_wrt_dd.setValue($c.ut.cGetToday("yyyymmdd"));
        if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "10") {
            // 기업분석보고서
            $c.stf.setObjectValue(txb_page_gbn, "report2");
        } else if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "12") {
            // 신규상장기업분석보고서
            $c.stf.setObjectValue(txb_page_gbn, "report5");
        } else if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "23") {
            //기업분석보고서(영문)
            $c.stf.setObjectValue(txb_page_gbn, "report2");
        } else if ($c.stf.getObjectValue(rdo_kosdaq_bbs_tp_cd) == "13") {
            // 성장성보고서
            $c.stf.setObjectValue(txb_page_gbn, "report5");
        } else {
            $c.stf.setObjectValue(txb_page_gbn, "report2");
        }
        if (js_market == "1" || js_market == "2" || js_market == "6") {
            rdo_mkt_tp_cd.setValue(js_market); //시장구분

        } else {
            rdo_mkt_tp_cd.setValue('1');
        }
        rdo_kosdaq_bbs_tp_cd.setValue('10'); //보고서구분 : 디폴트 기업분석보고서		

    }
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
